require_once 'connection.php';
$active='orders';$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$sql="SELECT o.*,u.First_Name,u.Last_Name FROM orders o JOIN Users u ON u.ID=o.User_id WHERE 1";$types='';$params=[];if($q!==''){ $sql.=" AND (o.Order_id LIKE ? OR o.Receiver_Name LIKE ? OR o.Receiver_Phone LIKE ?)";$types.='sss';$like="%$q%";$params=[$like,$like,$like];}if($status!==''){ $sql.=" AND o.Status=?";$types.='s';$params[]=$status;}$sql.=" ORDER BY o.Created_At DESC";$st=mysqli_prepare($con,$sql);if($types)mysqli_stmt_bind_param($st,$types,...$params);mysqli_stmt_execute($st);$rs=mysqli_stmt_get_result($st);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders — JuttaPasal</title><link rel="stylesheet" href="style.css"></head><body><?php include 'admin_sidebar.php';?><main class="admin-main"><div class="admin-topbar"><div><div class="eyebrow"><span class="dot"></span>SALES MANAGEMENT</div><h1>Orders</h1><p>Track customer orders, payments and delivery status.</p></div></div><div class="jp-panel"><form class="jp-toolbar" method="get"><input class="jp-input" name="q" value="<?=h($q)?>" placeholder="Search order, name or phone..."><select class="jp-select" name="status"><option value="">All statuses</option><?php foreach(['processing','packing','shipping','delivered','cancelled'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><button class="btn-jp secondary" type="submit"><?=icon('search')?> Search</button></form><div style="overflow-x:auto"><table class="jp-table"><thead><tr><th>Order</th><th>Customer</th><th>Delivery</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if(mysqli_num_rows($rs)===0):?><tr><td colspan="7" class="jp-empty">No orders found.</td></tr><?php else:while($o=mysqli_fetch_assoc($rs)):?><tr><td><b>#<?=h($o['Order_id'])?></b><br><small><?=h(date('M d, Y H:i',strtotime($o['Created_At'])))?></small></td><td><b><?=h($o['Receiver_Name'])?></b><br><small><?=h($o['Receiver_Phone'])?></small></td><td><?=h($o['City'])?><br><small><?=h($o['Delivery_Address'])?></small></td><td><b>Rs. <?=number_format($o['Total_Amount'],2)?></b></td><td><b><?=h(strtoupper($o['Payment_Method']))?></b><br><small class="<?=$o['Payment_Status']==='paid'?'payment-paid':'payment-unpaid'?>"><?=h($o['Payment_Status'])?></small></td><td><span class="status-pill status-<?=h($o['Status'])?>"><?=h($o['Status'])?></span></td><td><form class="order-status-form" method="post" action="order_update_status.php"><input type="hidden" name="order_id" value="<?=h($o['Order_id'])?>"><select name="status" onchange="this.form.submit()"><?php foreach(['processing','packing','shipping','delivered','cancelled'] as $s):?><option value="<?=$s?>" <?=$o['Status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></form></td></tr><?php endwhile;endif;?></tbody></table></div></div></main></body></html>
